function filterBy(arr, predicate) {
  const result = [];
  for (const item of arr) {
    if (predicate(item)) {
      result.push(item);
    }
  }
  return result;
}
const nums = [1, 2, 3, 4, 5, 6];
console.log(filterBy(nums, x => x % 2 === 0));
